import pytest
from solution import CORSMiddleware

@pytest.fixture
def cors():
    return CORSMiddleware(
        allowed_origins=['https://app.example.com', '*.trusted.com', 'http://localhost:3000'],
        allowed_methods=['GET', 'POST']
    )

def test_exact_match(cors):
    assert cors.is_origin_allowed('https://app.example.com') is True

def test_wildcard_match(cors):
    assert cors.is_origin_allowed('https://api.trusted.com') is True
    assert cors.is_origin_allowed('https://sub.trusted.com') is True

def test_rejected_origin(cors):
    assert cors.is_origin_allowed('https://evil.com') is False

def test_preflight_allowed(cors):
    headers = cors.handle_preflight('https://app.example.com', 'POST')
    assert 'Access-Control-Allow-Origin' in headers
    assert headers['Access-Control-Allow-Origin'] == 'https://app.example.com'

def test_preflight_rejected(cors):
    headers = cors.handle_preflight('https://evil.com', 'POST')
    assert 'Access-Control-Allow-Origin' not in headers

def test_cors_headers(cors):
    headers = cors.get_cors_headers('https://app.example.com')
    assert headers.get('Access-Control-Allow-Origin') == 'https://app.example.com'

def test_method_not_allowed(cors):
    headers = cors.handle_preflight('https://app.example.com', 'DELETE')
    assert 'Access-Control-Allow-Origin' not in headers or 'DELETE' not in headers.get('Access-Control-Allow-Methods', '')
